// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
// Changes: In-memory transport adapter for tests – a tiny fake server with the same revision rule as SQLite,
//          plus knobs to hold responses, inject failures and simulate other tabs.

import { defaultProjectData as defaultData, type ProjectData, type ProjectView } from './project'
import type { AdoptResult, DraftChangeResult, DraftRecord, ProjectRecord, SaveResult, SnapshotSummary } from '#/server/projects.server'
// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Human sees and opens drafts"
// Changes: Drafts in the fake server (fork, scripted agent edits, load, viewed revision).
import { PARTS, partEquals, readParts, writeParts, type Parts } from './parts'
// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Human edits drafts"
// Changes: Human draft saves with the store's per-part rule, project settings, scripted agent discard.
import { writeSettings } from './projectSettings'
import { TransportError, type CallOptions, type DraftSaveResult, type ProjectTransport, type SettingsSaveResult } from './projectTransport'

type Call = { op: string; input: unknown; opts?: CallOptions }

export function createFakeTransport(initial: ProjectRecord) {
  let clock = Date.parse(initial.updatedAt)
  const stamp = () => new Date((clock += 1000)).toISOString()
  const server = {
    record: structuredClone(initial) as ProjectRecord | null,
    view: structuredClone(initial.view) as ProjectView,
    snapshots: [] as { id: number; label: string; data: ProjectData }[],
    drafts: [] as DraftRecord[],
    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "Draft history"
    // Changes: Draft snapshots (ids shared with nothing else in the fake; oldest first).
    draftSnapshots: [] as { id: number; draftId: string; label: string; kind: SnapshotSummary['kind']; parts: Parts }[],
  }
  const calls: Call[] = []
  const held: (() => void)[] = []
  let holding = false
  let failure: TransportError | null = null

  // Every call: record it, optionally wait until released, optionally fail, then run against the fake server.
  const call = async <T>(op: string, input: unknown, opts: CallOptions | undefined, run: () => T): Promise<T> => {
    calls.push({ op, input: structuredClone(input), opts })
    if (holding) await new Promise<void>((resolve) => held.push(resolve))
    if (failure) throw failure
    return run()
  }

  const snapshotCurrent = (label: string) => {
    if (!server.record) return
    server.snapshots.push({ id: server.snapshots.length + 1, label, data: structuredClone(server.record.data) })
  }

  const replaceData = (data: ProjectData): ProjectRecord | null => {
    if (!server.record) return null
    server.record = { ...server.record, data: structuredClone(data), revision: server.record.revision + 1, updatedAt: stamp() }
    return structuredClone(server.record)
  }

  const transport: ProjectTransport = {
    save: (input, opts) =>
      call('save', input, opts, (): SaveResult => {
        const rec = server.record
        if (!rec || rec.id !== input.id) return { status: 'missing' }
        if (rec.revision !== input.baseRevision) return { status: 'conflict', project: structuredClone(rec) }
        const next = replaceData(input.data)!
        return { status: 'saved', revision: next.revision, updatedAt: next.updatedAt }
      }),
    saveView: (input, opts) =>
      call('saveView', input, opts, () => {
        server.view = structuredClone(input.view)
      }),
    replace: (input) =>
      call('replace', input, undefined, () => {
        snapshotCurrent(input.label)
        return replaceData(input.data)
      }),
    restore: (input) =>
      call('restore', input, undefined, () => {
        const snap = server.snapshots.find((s) => s.id === input.snapshotId)
        if (!snap) return null
        snapshotCurrent(`Pred obnovením: ${snap.label}`)
        return replaceData(snap.data)
      }),
    createSnapshot: (input) =>
      call('createSnapshot', input, undefined, (): SnapshotSummary | null => {
        if (!server.record) return null
        snapshotCurrent(input.label)
        return { id: server.snapshots.length, label: input.label, kind: 'named', auto: false, createdAt: stamp() }
      }),
    loadDraft: (input) =>
      call('loadDraft', input, undefined, () => {
        const draft = findDraft(input.draftId)
        return draft && server.record ? structuredClone({ project: { ...server.record, view: server.view }, draft }) : null
      }),
    markDraftViewed: (input) =>
      call('markDraftViewed', input, undefined, () => {
        const draft = findDraft(input.draftId)
        if (draft?.state === 'open') draft.humanViewedRevision = Math.max(draft.humanViewedRevision, Math.min(input.revision, draft.revision))
      }),
    saveDraft: (input, opts) =>
      call('saveDraft', input, opts, (): DraftSaveResult => {
        const draft = findDraft(input.draftId)
        if (!draft) return { status: 'missing' }
        if (draft.state !== 'open') return { status: 'ended', draft: structuredClone(draft) }
        // Same rule as the store: touched = sent parts that differ; stale only matters for parts changed since base.
        const current = writeParts(defaultData(), draft.parts)
        const next = writeParts(current, input.parts)
        const touched = PARTS.filter((part) => input.parts[part] !== undefined && !partEquals(part, current, next))
        const overlap = touched.filter((part) => draft.partRevisions[part] > input.baseRevision)
        if (overlap.length) return { status: 'conflict', draft: structuredClone(draft), parts: overlap }
        if (!touched.length) return { status: 'saved', draft: structuredClone(draft), changed: [] }
        draft.revision++
        for (const part of touched) draft.partRevisions[part] = draft.revision
        draft.parts = readParts(next)
        draft.lastChangedBy = 'human'
        draft.humanViewedRevision = draft.revision
        draft.updatedAt = stamp()
        return { status: 'saved', draft: structuredClone(draft), changed: touched }
      }),
    saveSettings: (input, opts) =>
      call('saveSettings', input, opts, (): SettingsSaveResult => {
        if (!server.record || server.record.id !== input.id) return { status: 'missing' }
        const next = replaceData(writeSettings(server.record.data, input.settings))!
        return { status: 'saved', revision: next.revision, updatedAt: next.updatedAt }
      }),
    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "Draft history"
    // Changes: Draft history in the fake server (same outcomes as the store: null when gone, rejected when ended).
    createDraftSnapshot: (input) =>
      call('createDraftSnapshot', input, undefined, (): SnapshotSummary | null => {
        const draft = openDraftOrThrow(input.draftId)
        if (!draft) return null
        const snap = { id: 100 + server.draftSnapshots.length + 1, draftId: draft.id, label: input.label, kind: 'named' as const, parts: structuredClone(draft.parts) }
        server.draftSnapshots.push(snap)
        return { id: snap.id, label: snap.label, kind: 'named', auto: false, createdAt: stamp() }
      }),
    restoreDraft: (input) =>
      call('restoreDraft', input, undefined, (): DraftRecord | null => {
        const draft = openDraftOrThrow(input.draftId)
        const snap = server.draftSnapshots.find((s) => s.id === input.snapshotId && s.draftId === input.draftId)
        if (!draft || !snap) return null
        server.draftSnapshots.push({
          id: 100 + server.draftSnapshots.length + 1,
          draftId: draft.id,
          label: `Pred obnovením „${snap.label}“`,
          kind: 'safety',
          parts: structuredClone(draft.parts),
        })
        draft.revision++
        for (const part of PARTS) if (JSON.stringify(draft.parts[part]) !== JSON.stringify(snap.parts[part])) draft.partRevisions[part] = draft.revision
        draft.parts = structuredClone(snap.parts)
        draft.lastChangedBy = 'human'
        draft.humanViewedRevision = draft.revision
        draft.updatedAt = stamp()
        return structuredClone(draft)
      }),
    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "Adopt and discard in the editor"
    // Changes: Adopt (safety snapshot of the project, chosen parts written, final snapshot) and discard, like the store.
    adoptDraft: (input) =>
      call('adoptDraft', input, undefined, (): AdoptResult => {
        const draft = findDraft(input.draftId)
        if (!draft || !server.record) return { status: 'missing' }
        if (draft.state !== 'open') return { status: 'ended', draft: structuredClone(draft) }
        if (server.record.revision !== input.projectRevision) return { status: 'stale', project: structuredClone(server.record), draft: structuredClone(draft) }
        snapshotCurrent(`Pred prevzatím návrhu „${draft.label}“`)
        const chosen = Object.fromEntries(input.parts.map((part) => [part, draft.parts[part]])) as Partial<Parts>
        const project = replaceData(writeParts(server.record.data, chosen))!
        endDraft(draft, 'adopted', `Prevzatý návrh „${draft.label}“`)
        return { status: 'adopted', project, draft: structuredClone(draft) }
      }),
    discardDraft: (input) =>
      call('discardDraft', input, undefined, (): DraftChangeResult => {
        const draft = findDraft(input.draftId)
        if (!draft) return { status: 'missing' }
        if (draft.state !== 'open') return { status: 'ended', draft: structuredClone(draft) }
        endDraft(draft, 'discarded', `Zahodený návrh „${draft.label}“`)
        return { status: 'saved', draft: structuredClone(draft) }
      }),
  }

  const endDraft = (draft: DraftRecord, state: 'adopted' | 'discarded', label: string) => {
    server.draftSnapshots.push({ id: 100 + server.draftSnapshots.length + 1, draftId: draft.id, label, kind: 'final', parts: structuredClone(draft.parts) })
    draft.state = state
    draft.endedAt = draft.updatedAt = stamp()
  }

  const openDraftOrThrow = (id: string) => {
    const draft = findDraft(id)
    if (draft && draft.state !== 'open') throw new TransportError('Návrh je ukončený – jeho históriu už nemožno meniť.', false)
    return draft
  }

  const findDraft = (id: string) => server.drafts.find((d) => d.id === id)

  return {
    transport,
    server,
    calls,
    /** Calls made with this op name. */
    callsOf: (op: string) => calls.filter((c) => c.op === op),
    /** From now on calls wait until `release()`. */
    hold: () => void (holding = true),
    /** Lets every waiting call through and stops holding. */
    release: () => {
      holding = false
      held.splice(0).forEach((r) => r())
    },
    /** Every following call fails with this error (null = stop failing). */
    failWith: (err: TransportError | null) => void (failure = err),
    /** Another tab saved this document. */
    externalSave: (data: ProjectData) => replaceData(data),
    /** Another tab deleted the project. */
    deleteProject: () => void (server.record = null),
    /** An agent forks a draft from the project's current parts. */
    createDraft(label: string): DraftRecord {
      const parts = readParts(server.record!.data)
      const ts = stamp()
      const draft: DraftRecord = {
        id: `d${server.drafts.length + 1}`,
        projectId: server.record!.id,
        label,
        state: 'open',
        revision: 1,
        partRevisions: { definition: 1, grammarRules: 1, precTable: 1, reductionRules: 1 },
        lastChangedBy: 'agent',
        humanViewedRevision: 0,
        parts,
        base: { projectRevision: server.record!.revision, parts: structuredClone(parts) },
        createdAt: ts,
        updatedAt: ts,
        endedAt: null,
      }
      server.drafts.push(draft)
      return structuredClone(draft)
    },
    /** An agent changes parts of an open draft (a new draft revision). */
    agentEdit(draftId: string, change: Partial<Parts>): DraftRecord {
      const draft = findDraft(draftId)!
      draft.revision++
      for (const part of PARTS) if (change[part] !== undefined) draft.partRevisions[part] = draft.revision
      draft.parts = readParts(writeParts(writeParts(defaultData(), draft.parts), change))
      draft.lastChangedBy = 'agent'
      draft.updatedAt = stamp()
      return structuredClone(draft)
    },
    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "Draft history"
    // Changes: Inspect a draft's history; end a draft as discarded.
    /** A draft's snapshots, oldest first, with the grammar rules they hold. */
    draftSnapshots: (draftId: string) =>
      server.draftSnapshots.filter((s) => s.draftId === draftId).map((s) => ({ id: s.id, label: s.label, kind: s.kind, grammarRules: s.parts.grammarRules })),
    /** The draft is discarded (elsewhere). */
    discardDraft(draftId: string) {
      const draft = findDraft(draftId)!
      draft.state = 'discarded'
      draft.endedAt = stamp()
    },
    /** The fake server's current copy of a draft. */
    draft: (draftId: string) => structuredClone(findDraft(draftId)),
  }
}
